// Núcleo · Normalizar evento: valida o contrato {tarefa, etapa, agente, status, resumo, sessao, ts}.
const ETAPAS = ['jira', 'plano', 'aprovado', 'implementacao', 'qa', 'seguranca', 'review', 'commit', 'pr', 'registro', 'concluida', 'pausada'];
const STATUS = ['iniciada', 'concluida', 'falhou', 'bloqueada'];
const limpar = (v, max) => String(v === undefined || v === null ? '' : v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);

const saida = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const b = (j.body && typeof j.body === 'object') ? j.body : ((j.evento && typeof j.evento === 'object') ? j.evento : j);
  const erros = [];

  const tarefa = limpar(b.tarefa, 40);
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,39}$/.test(tarefa)) erros.push('tarefa ausente ou inválida');

  const etapa = limpar(b.etapa, 24).toLowerCase();
  if (!ETAPAS.includes(etapa)) erros.push('etapa fora do contrato: ' + (etapa || 'vazia'));

  const status = limpar(b.status, 16).toLowerCase();
  if (!STATUS.includes(status)) erros.push('status fora do contrato: ' + (status || 'vazio'));

  const agente = limpar(b.agente, 60).toLowerCase() || 'orquestrador';
  const agente_curto = agente.replace(/^dev-/, '');
  const resumo = limpar(b.resumo, 400);
  const sessao = limpar(b.sessao, 80);

  let ts = new Date().toISOString();
  if (b.ts !== undefined && b.ts !== null && b.ts !== '') {
    const t = typeof b.ts === 'number' ? b.ts : Date.parse(String(b.ts));
    if (Number.isFinite(t)) ts = new Date(t).toISOString();
    else erros.push('ts inválido');
  }

  saida.push({ json: { operacao: 'normalizar_evento', tarefa, etapa, agente, agente_curto, status, resumo, sessao, ts, valido: erros.length === 0, erros } });
}
return saida;

// Núcleo · Registrar estado e evento.
// Armazenamento: static data do próprio _core (compartilhado entre os mestres e o painel, que sempre passam por aqui).
// Estruturas: tarefas { [tarefa]: {tarefa, titulo, etapa, agente, status, atualizado_em} } e eventos [ {ts, tarefa, etapa, agente, status, resumo} ].
const MAX_EVENTOS = 500;
const MAX_TAREFAS = 200;
const est = $getWorkflowStaticData('global');
est.tarefas = est.tarefas || {};
est.eventos = est.eventos || [];

const saida = [];
for (const item of $input.all()) {
  const e = item.json;
  if (e.valido === false) { saida.push(item); continue; }
  const t = est.tarefas[e.tarefa] || { tarefa: e.tarefa, titulo: '', etapa: e.etapa, agente: e.agente, status: e.status, atualizado_em: '' };
  if (!t.titulo && e.etapa === 'jira' && e.resumo) t.titulo = e.resumo.slice(0, 120);
  // Eventos fora de ordem entram no histórico, mas não rebaixam o estado atual.
  if (!t.atualizado_em || e.ts >= t.atualizado_em) {
    t.etapa = e.etapa; t.agente = e.agente; t.status = e.status; t.atualizado_em = e.ts; t.sessao = e.sessao;
  }
  est.tarefas[e.tarefa] = t;
  est.eventos.push({ ts: e.ts, tarefa: e.tarefa, etapa: e.etapa, agente: e.agente, status: e.status, resumo: e.resumo });
  saida.push({ json: { ...e, registrado: true } });
}
if (est.eventos.length > MAX_EVENTOS) est.eventos.splice(0, est.eventos.length - MAX_EVENTOS);
const ids = Object.keys(est.tarefas);
if (ids.length > MAX_TAREFAS) {
  ids.sort((a, b) => String(est.tarefas[a].atualizado_em).localeCompare(String(est.tarefas[b].atualizado_em)));
  for (const id of ids.slice(0, ids.length - MAX_TAREFAS)) delete est.tarefas[id];
}
return saida;

// Núcleo · Tratar erro: classifica o problema e guarda um rastro curto.
// Evento inválido vai para "descartados" (nunca entra em tarefas/eventos). Falha/bloqueio vira alerta.
const est = $getWorkflowStaticData('global');
est.descartados = est.descartados || [];
const agora = new Date().toISOString();
const saida = [];
for (const item of $input.all()) {
  const e = item.json;
  if (e.valido === false) {
    est.descartados.push({ ts: agora, motivo: (e.erros || []).join('; ').slice(0, 300) });
    saida.push({ json: { ...e, alerta: { nivel: 'aviso', mensagem: 'Evento descartado: ' + (e.erros || []).join('; ') } } });
  } else {
    const nivel = e.status === 'falhou' ? 'erro' : 'atencao';
    const verbo = e.status === 'falhou' ? 'falhou' : 'ficou bloqueada';
    saida.push({ json: { ...e, alerta: { nivel, mensagem: 'A tarefa ' + e.tarefa + ' ' + verbo + ' na etapa ' + e.etapa + ' (' + e.agente + '). ' + (e.resumo || '') } } });
  }
}
if (est.descartados.length > 50) est.descartados.splice(0, est.descartados.length - 50);
return saida;

// Núcleo · Notificar. Hoje só monta a mensagem (canal "painel").
// PONTO DE EXTENSÃO: ligar aqui Slack, e-mail ou push quando houver credencial. Nunca colocar dado de saúde na mensagem.
return $input.all().map((item) => {
  const e = item.json;
  const mensagem = (e.alerta && e.alerta.mensagem)
    ? e.alerta.mensagem
    : ('Tarefa ' + e.tarefa + ' chegou à etapa ' + e.etapa + ' (' + e.status + ').');
  return { json: { ...e, notificacao: { canal: 'painel', enviada: false, mensagem } } };
});

// Núcleo · Ler estado (usado pelo painel).
const est = $getWorkflowStaticData('global');
const tarefas = Object.values(est.tarefas || {}).sort((a, b) => String(b.atualizado_em).localeCompare(String(a.atualizado_em)));
const eventos = (est.eventos || []).slice(-40).reverse();
const contadores = {
  tarefas: tarefas.length,
  em_andamento: tarefas.filter((t) => t.status === 'iniciada').length,
  concluidas: tarefas.filter((t) => t.etapa === 'concluida' && t.status === 'concluida').length,
  bloqueadas: tarefas.filter((t) => t.status === 'falhou' || t.status === 'bloqueada').length,
  eventos: (est.eventos || []).length,
  descartados: (est.descartados || []).length,
};
return [{ json: { operacao: 'ler_estado', tarefas, eventos, contadores, gerado_em: new Date().toISOString() } }];
